import io.netty.channel.Channel;
import io.netty.buffer.ByteBuf;
import io.netty.buffer.Unpooled;

import java.net.SocketAddress;
import java.nio.charset.StandardCharsets;

import org.junit.Test;
import org.junit.Assert;

import org.traccar.helper.UnitsConverter;
import org.traccar.Protocol;
import org.traccar.model.Position;
import org.traccar.protocol.WatchProtocolDecoder;

import static org.mockito.Mockito.*;

public class WatchProtocolDecoderTest {

    private static final String DEVICE_ID = "123456789012345";

    private ByteBuf buf(String string) {
        return Unpooled.wrappedBuffer(string.getBytes(StandardCharsets.US_ASCII));
    }

    @Test
    public void decodeTest() throws Exception {
        Channel channel = mock(Channel.class);
        SocketAddress socketAddress = mock(SocketAddress.class);
        Protocol protocol = new Protocol("watch") { };
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);

        // Data for "UD" type
        ByteBuf msgUD = buf("[3g*123456789012345*ud,030105,061653,a,4650424,0190768,508180,05]");
        Position posUD = (Position) decoder.decode(channel, socketAddress, msgUD);
        Assert.assertEquals(UnitsConverter.knotsFromKph(508.18), posUD.getSpeed());

        // Data for "AL" type
        ByteBuf msgAL = buf("[3g*123456789012345*ud,030105,091653,a,4650424,0190768,508180,05]");
        Position posAL = (Position) decoder.decode(channel, socketAddress, msgAL);
        Assert.assertEquals(Position.ALARM_GENERAL, posAL.get(Position.KEY_ALARM));

        // Empty message
        ByteBuf msgEmpty = buf("");
        Assert.assertNotNull(decoder.decode(channel, socketAddress, msgEmpty));
    }
}
